from pathlib import Path
import json
css='''
/* Chi tiết nhận diện của từng cửa hàng. */
.tech{--paper:#f1f3f3!important;font-family:'Segoe UI',Arial,sans-serif}.tech .brand{letter-spacing:4px}.tech .hero{background:#e2e8e9;padding:32px;grid-template-columns:1fr 1fr}.tech .hero img{height:400px}.tech .item{background:white;padding:18px;border:1px solid #d3dadb}.tech .item img{height:210px;object-fit:cover}.tech .item .price{font-size:23px}.tech .item small{font-family:Consolas,monospace}.bookstore .hero{grid-template-columns:1.1fr .9fr;border-bottom:2px solid #345e50;padding-bottom:35px}.bookstore .hero img{height:420px}.bookstore .hero h1{font-size:56px}.bookstore .grid{grid-template-columns:1fr 1fr}.bookstore .item{display:grid;grid-template-columns:150px 1fr;gap:0 24px;padding-bottom:25px}.bookstore .item img{grid-row:1/7;height:220px}.bookstore .item p{margin-top:10px}.bookstore .item button{justify-self:start}.organic .hero{grid-template-columns:1fr 1fr;background:#e8eddf;padding:32px}.organic .hero h1{font-size:54px}.organic .hero img{height:400px}.organic .item img{height:240px}.organic .item .price{font-size:22px}.flowers .hero img{height:570px}.flowers .hero h1{font-size:60px;font-weight:500}.flowers .brand{font-weight:500;letter-spacing:4px}.flowers .item img{height:350px}.flowers .grid{gap:42px 28px}.furniture .hero{grid-template-columns:.75fr 1.25fr}.furniture .hero img{height:580px}.furniture .hero h1{font-size:58px}.furniture .grid{grid-template-columns:1fr 1fr}.furniture .item img{height:330px}.handmade .hero{grid-template-columns:1fr 1fr}.handmade .hero img{height:480px}.handmade .hero h1{font-weight:500}.handmade .item{border-bottom:1px solid #ad9681}.handmade .item img{height:285px}.gallery .brand{letter-spacing:6px}.appointments .hero{background:#ede8df;padding:35px}.appointments .hero img{height:420px}.appointments .hero h1{font-size:52px}.appointments .item img{display:none}.appointments .grid{grid-template-columns:1fr 1fr}.appointments .item{padding:25px;background:white;border:1px solid #ddd}.appointments .item small{color:#6e6150}.appointments .item .price{font-size:24px}.language .hero{background:#e7edf2}.coding .hero{background:#e1e9e9}.coding .brand{font-family:Consolas,monospace;letter-spacing:-1px}.coding .hero img{filter:grayscale(1)}.expenses .utility-head,.calendar .utility-head{border-bottom:2px solid var(--accent)}.mini-tools .utility-head{max-width:750px}.todo main{max-width:1060px}
@media(max-width:850px){.tech .hero,.bookstore .hero,.organic .hero,.furniture .hero,.handmade .hero{grid-template-columns:1fr}.bookstore .hero h1,.flowers .hero h1,.furniture .hero h1,.organic .hero h1,.appointments .hero h1{font-size:42px}.furniture .hero img,.flowers .hero img{height:380px}.tech .hero,.organic .hero,.appointments .hero{padding:22px}.bookstore .grid{grid-template-columns:1fr}}@media(max-width:520px){.furniture .grid,.appointments .grid{grid-template-columns:1fr}.bookstore .item{grid-template-columns:95px 1fr;gap:0 15px}.bookstore .item img{height:165px}.tech .hero h1{font-size:38px}.tech .hero img,.organic .hero img{height:260px}.flowers .hero img{height:380px}.flowers .item img{height:340px}}
'''
for c in json.loads(Path('scripts/projects.json').read_text(encoding='utf-8')):
 f=Path(c[0])/'css/style.css';f.write_text(f.read_text(encoding='utf-8')+css,encoding='utf-8')
 for f in Path(c[0]).glob('*.html'):
  s=f.read_text(encoding='utf-8').replace('<dialog id="detail">','<dialog id="detail" aria-label="Chi tiết nội dung">');f.write_text(s,encoding='utf-8')
Path('scripts/brand-details.css').write_text(css,encoding='utf-8')
